cd /tmp/hardvm && python - <<'EOF'
import pefile, struct
pe = pefile.PE('vm_guard.exe')
base = pe.OPTIONAL_HEADER.ImageBase
# Find code that computes VA from section RVA + base: look for mov r, imm32 of 0x1e000/0x1f000 or 0x1e/0x1f, and add base
for s in pe.sections:
    if s.Name.rstrip(b'\x00') == b'.text':
        text = s.get_data(); va = base + s.VirtualAddress
for name, tgt in [(b'.vmz', 0x1e000), (b'.fptable', 0x1f000)]:
    for w in (4,2):
        pat = struct.pack('<I' if w==4 else '<H', tgt)
        idx=0; found=[]
        while True:
            i = text.find(pat, idx)
            if i<0: break
            found.append(i); idx=i+1
        if found:
            print(name, w, [hex(va+f) for f in found[:10]])
# Also check .rdata / .data for pointers
for sn in ('.rdata','.data'):
    for s in pe.sections:
        if s.Name.rstrip(b'\x00') == sn.encode():
            d = s.get_data(); dva = base+s.VirtualAddress
            for name, tgt in [('vmz', 0x14001e000), ('fptable', 0x14001f000)]:
                pat = struct.pack('<Q', tgt)
                idx=0
                while True:
                    i = d.find(pat, idx)
                    if i<0: break
                    print(f"{sn} ptr to {name} at", hex(dva+i), "offset", hex(s.PointerToRawData+i))
                    idx=i+1
